signal.description:
Emitted when this scene starts replicating to [param player]. [member viewers] already includes them. On the server, spawn arriving players here.
[codeblock]
func place(player: NetwPlayer, level: NetwScene) -> void:
    if player.bodies.is_empty():
        level.root.add_child(Netw.spawn_player(player, make_player))
[/codeblock]
